let imageZones = [], attributeService, broadcastService, params, controller, overlays = [];

self.onInit = function() {
    self.ctx.$scope.mapWidget.onInit();
    broadcastService = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('broadcastService'));
    attributeService = self.ctx.$scope.$injector.get(self.ctx.servicesMap.get('attributeService'));

    broadcastService.on('geofencesUpdate', (event, args) => {
        self.ctx.updateAliases();
        self.ctx.detectChanges();
    });

    self.ctx.$scope.saveCoordinates = function(){
        console.log(imageZones)
        if(imageZones && imageZones.length){
            const fourthPoint = findFourthPoint(imageZones[0].pointA, imageZones[0].pointB, imageZones[0].pointC);

            attributeService.saveEntityAttributes(imageZones[0].id, 'SERVER_SCOPE',
                [{key: 'pointA', value: imageZones[0].pointA}, 
                {key: 'pointB', value: imageZones[0].pointB}, 
                {key: 'pointC', value: imageZones[0].pointC}, 
                {key: 'perimeter', value: [
                    fourthPoint,
                    imageZones[0].pointB,
                    imageZones[0].pointA,
                    imageZones[0].pointC
                ]}]).subscribe(() => {
                    broadcastService.broadcast('coordinatesSaved', 'Some data');
                    self.ctx.showSuccessToast("Coordinates were updated successfully!", 4000, "bottom", "left", "layout");
                });
        }
    };

    controller = self.ctx.stateController;
    params = controller.getStateParams();
};

